import { api, tags, urlUtils, getClientProps } from '@igblsln/store';
const API_PATH = '/estimate/sectionworksheetmapping/';
export const sectionWorkSheetMappingApi = api.injectEndpoints({
    overrideExisting: false,
    endpoints: (build) => ({
        saveSectionWorkSheetMapping: build.mutation({
            query: (body) => ({
                url: API_PATH,
                method: 'POST',
                body: Object.assign(Object.assign({}, body), getClientProps()),
            }),
            invalidatesTags: [{ type: tags.ESTIMATION_WORKSHEET, id: 'LIST' }],
        }),
        getSectionWorkSheetMapping: build.query({
            query: ({ project, block }) => ({
                url: urlUtils(API_PATH, `?project=${project}&block=${block}&without_pagination=1`),
            }),
            providesTags: [{ type: tags.ESTIMATION_WORKSHEET, id: 'LIST' }],
        }),
    }),
});
export const { useSaveSectionWorkSheetMappingMutation, useGetSectionWorkSheetMappingQuery, } = sectionWorkSheetMappingApi;
