export const PARENT_TYPES = [
    { key: 'sump', label: 'Sump', hasChildren: false, children: [] },
    { key: 'oht', label: 'OHT', hasChildren: false, children: [] },
    { key: 'floor-shell', label: 'Floor Shell', hasChildren: true, children: ['Columns', 'Roof'] },
    { key: 'staircase', label: 'Staircase', hasChildren: true, children: ['Staircase Flight', 'Head Room'] },
    { key: 'lift', label: 'Lift', hasChildren: true, children: ['Lift Shaft', 'Machine Room', 'Lift Footing'] },
    { key: 'apartment', label: 'Apartment', hasChildren: true, children: ['Bed Room', 'Living Room', 'Kitchen', 'Bathroom'] },
    { key: 'ots', label: 'OTS', hasChildren: true, children: ['OTS Floor'] },
];
export const findParentType = (key) => PARENT_TYPES.find((p) => p.key === key);
