const buildMockWorkScreens = () => {
    const seen = new Set();
    const result = [];
    let counter = 0;
    Object.values(WORKS_BY_SECTION_TYPE).forEach((items) => {
        items.forEach((item) => {
            const dedupeKey = `${item.category}__${item.workName}`;
            if (seen.has(dedupeKey))
                return;
            seen.add(dedupeKey);
            const categoryKey = CATEGORY_DESCR_BY_NAME[item.category];
            counter += 1;
            result.push({
                key: counter,
                id: counter,
                name: item.workName,
                descr: item.workName,
                category_key: categoryKey,
                category_descr: item.category,
                description: '',
                segments: [],
                task_details: [],
                item_kit_details: [],
                spec_param_details: [],
            });
        });
    });
    return result;
};
export const MOCK_WORK_SCREENS = buildMockWorkScreens();
export const WORK_NAMES_BY_CATEGORY = MOCK_WORK_SCREENS.reduce((acc, ws) => {
    const cat = ws.category_descr;
    if (!acc[cat])
        acc[cat] = [];
    if (!acc[cat].includes(ws.name))
        acc[cat].push(ws.name);
    return acc;
}, {});
