const genericMeasurementConfig = (label, value, initialMeasurements = ['Length', 'Breadth', 'Height']) => ({
    label,
    value,
    defaultScope: 'Project Specific',
    defaultMeasurementType: 'Length',
    tabs: [
        {
            id: `${value}-measurement`,
            title: 'MEASUREMENT',
            columns: measurementColumns(),
            initialRows: initialMeasurements.map((name) => createMeasurementRow(name, 'Length')),
            createRow: () => createMeasurementRow('New Measurement', 'Length'),
            addLabel: 'Add Measurement',
            allowAdd: true,
            showHeaderAdd: false,
        },
    ],
});
export const SECTION_CONFIGS = {
    bedroom: bedroomConfig,
    bathroom: bathroomConfig,
    oht: ohtConfig,
    sump: sumpConfig,
    apartment: apartmentConfig,
    'floor-shell': genericMeasurementConfig('Floor Shell', 'floor-shell', ['Column Length', 'Column Breadth', 'Column Height', 'Roof Slab Thickness']),
    staircase: genericMeasurementConfig('Staircase', 'staircase', ['Flight Length', 'Flight Width', 'Riser Height', 'Tread Depth']),
    lift: genericMeasurementConfig('Lift', 'lift', ['Shaft Length', 'Shaft Width', 'Shaft Height', 'Pit Depth', 'Headroom Height']),
    ots: genericMeasurementConfig('OTS', 'ots', ['Floor Length', 'Floor Width', 'Floor Thickness']),
};
export const buildBlankSectionRows = (section) => section.initialRows.map((row, index) => (Object.assign({ id: createId(section.id, index) }, row)));
export const getSectionLabel = (value) => SECTION_CONFIGS[value].label;
export const renderSectionTitle = (section, sectionName) => section.titleRenderer ? section.titleRenderer(sectionName) : section.title;
export const APARTMENT_CHILD_LABELS = APARTMENT_CHILD_SECTIONS.reduce((acc, child) => (Object.assign(Object.assign({}, acc), { [child.key]: child.label })), {});
