import { api, tags, urlUtils } from '@igblsln/store';
const API_PATH = '/estimate/subsections/';
export const subSectionApi = api.injectEndpoints({
    overrideExisting: false,
    endpoints: (build) => ({
        listSubSections: build.query({
            query: ({ project, block }) => {
                const params = new URLSearchParams();
                if (project)
                    params.append('project', project.toString());
                if (block)
                    params.append('block', block.toString());
                params.append('without_pagination', '1');
                return {
                    url: urlUtils(API_PATH, `?${params.toString()}`),
                };
            },
            providesTags: [{ type: tags.SUB_SECTION, id: 'LIST' }],
        }),
        addSubSections: build.mutation({
            query(data) {
                return {
                    url: API_PATH,
                    method: 'POST',
                    body: data,
                };
            },
            invalidatesTags: [{ type: tags.SUB_SECTION, id: 'LIST' }],
        }),
        updateSubSections: build.mutation({
            query(data) {
                return {
                    url: `${API_PATH}${data.block_key}`,
                    method: 'PUT',
                    body: data,
                };
            },
            invalidatesTags: [{ type: tags.SUB_SECTION, id: 'LIST' }],
        }),
    }),
});
export const { useListSubSectionsQuery, useAddSubSectionsMutation, useUpdateSubSectionsMutation, } = subSectionApi;
